// Adapter Sanity — siapkan request ke Sanity HTTP API dari kredensial user (token Editor)
// draft            → Mutations API: createOrReplace "drafts.<id>"
// publish + artikel → Mutations API: createOrReplace "<id>" + hapus "drafts.<id>"
// publish tanpa artikel (postId draf lama) → Actions API: sanity.action.document.publish (isi draf apa adanya)
const IN = $input.first().json;
const S = (IN.cms || {}).sanity || {};
const projectId = String(S.projectId || '').trim().toLowerCase();
const dataset = String(S.dataset || 'production').trim();
const docType = String(S.docType || 'post').trim() || 'post';
const bodyField = String(S.bodyField || 'body').trim() || 'body';
const action = IN.action === 'publish' ? 'publish' : 'draft';
const A = IN.article && typeof IN.article === 'object' ? IN.article : null;
const API = 'https://' + projectId + '.api.sanity.io/v2025-02-19';

// ===== Markdown mini-parser (dipakai adapter WordPress & Wix) =====
// parseMarkdown(md) -> [{type:'heading',level,inlines}|{type:'paragraph',inlines}|{type:'list',ordered,items:[inlines]}|{type:'quote',inlines}]
// inlines: [{text, bold, italic, code, href}]
function parseInline(s) {
  const out = []; const src = String(s || '');
  const push = (t, m) => { if (t) out.push(Object.assign({ text: t }, m || {})); };
  const re = /(\*\*([^*]+)\*\*|__([^_]+)__|\*([^*\n]+)\*|_([^_\n]+)_|`([^`]+)`|\[([^\]]+)\]\(([^)\s]+)\))/g;
  let m; let last = 0;
  while ((m = re.exec(src))) {
    push(src.slice(last, m.index));
    if (m[2] || m[3]) push(m[2] || m[3], { bold: true });
    else if (m[4] || m[5]) push(m[4] || m[5], { italic: true });
    else if (m[6]) push(m[6], { code: true });
    else if (m[7]) push(m[7], { href: m[8] });
    last = m.index + m[0].length;
  }
  push(src.slice(last));
  return out;
}
function parseMarkdown(md) {
  const lines = String(md || '').replace(/\r/g, '').split('\n');
  const blocks = []; let para = []; let list = null;
  const flushPara = () => { if (para.length) { blocks.push({ type: 'paragraph', inlines: parseInline(para.join(' ')) }); para = []; } };
  const flushList = () => { if (list) { blocks.push(list); list = null; } };
  for (const raw of lines) {
    const t = raw.trim();
    if (!t) { flushPara(); flushList(); continue; }
    let m;
    if ((m = t.match(/^(#{1,6})\s+(.*)$/))) { flushPara(); flushList(); blocks.push({ type: 'heading', level: Math.min(Math.max(m[1].length, 2), 4), inlines: parseInline(m[2].replace(/\s#+$/, '')) }); continue; }
    if ((m = t.match(/^[-*+]\s+(.*)$/))) { flushPara(); if (!list || list.ordered) { flushList(); list = { type: 'list', ordered: false, items: [] }; } list.items.push(parseInline(m[1])); continue; }
    if ((m = t.match(/^\d+[.)]\s+(.*)$/))) { flushPara(); if (!list || !list.ordered) { flushList(); list = { type: 'list', ordered: true, items: [] }; } list.items.push(parseInline(m[1])); continue; }
    if ((m = t.match(/^>\s?(.*)$/))) { flushPara(); flushList(); blocks.push({ type: 'quote', inlines: parseInline(m[1]) }); continue; }
    if (/^(-{3,}|\*{3,})$/.test(t)) { flushPara(); flushList(); continue; }
    flushList(); para.push(t);
  }
  flushPara(); flushList();
  return blocks;
}
const escHtml = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function inlinesToHtml(inl) {
  return inl.map(x => { let h = escHtml(x.text); if (x.code) h = '<code>' + h + '</code>'; if (x.bold) h = '<strong>' + h + '</strong>'; if (x.italic) h = '<em>' + h + '</em>'; if (x.href) h = '<a href="' + escHtml(x.href) + '" target="_blank" rel="noopener">' + h + '</a>'; return h; }).join('');
}
function markdownToHtml(md) {
  return parseMarkdown(md).map(b => {
    if (b.type === 'heading') return '<h' + b.level + '>' + inlinesToHtml(b.inlines) + '</h' + b.level + '>';
    if (b.type === 'quote') return '<blockquote><p>' + inlinesToHtml(b.inlines) + '</p></blockquote>';
    if (b.type === 'list') return (b.ordered ? '<ol>' : '<ul>') + b.items.map(it => '<li>' + inlinesToHtml(it) + '</li>').join('') + (b.ordered ? '</ol>' : '</ul>');
    return '<p>' + inlinesToHtml(b.inlines) + '</p>';
  }).join('\n');
}
// Ricos (Wix rich content)
function markdownToRicos(md) {
  let seq = 0; const nid = () => 'n' + (++seq).toString(36) + Date.now().toString(36).slice(-4);
  const textNode = x => { const dec = []; if (x.bold) dec.push({ type: 'BOLD', fontWeightValue: 700 }); if (x.italic) dec.push({ type: 'ITALIC', italicData: true }); if (x.href) dec.push({ type: 'LINK', linkData: { link: { url: x.href, target: 'BLANK' } } }); return { type: 'TEXT', id: '', nodes: [], textData: { text: x.text, decorations: dec } }; };
  const paragraph = inl => ({ type: 'PARAGRAPH', id: nid(), nodes: inl.map(textNode), paragraphData: {} });
  const nodes = [];
  for (const b of parseMarkdown(md)) {
    if (b.type === 'heading') nodes.push({ type: 'HEADING', id: nid(), nodes: b.inlines.map(textNode), headingData: { level: b.level } });
    else if (b.type === 'quote') nodes.push({ type: 'BLOCKQUOTE', id: nid(), nodes: [paragraph(b.inlines)], blockquoteData: {} });
    else if (b.type === 'list') nodes.push({ type: b.ordered ? 'ORDERED_LIST' : 'BULLETED_LIST', id: nid(), nodes: b.items.map(it => ({ type: 'LIST_ITEM', id: nid(), nodes: [paragraph(it)] })), [b.ordered ? 'orderedListData' : 'bulletedListData']: { indentation: 0 } });
    else nodes.push(paragraph(b.inlines));
  }
  return { nodes, metadata: { version: 1 } };
}
// Portable Text (Sanity block content)
function markdownToPortableText(md) {
  let seq = 0; const key = () => 'k' + (++seq).toString(36) + Math.random().toString(36).slice(2, 8);
  const block = (inl, extra) => {
    const markDefs = [];
    const children = (inl.length ? inl : [{ text: '' }]).map(x => {
      const marks = [];
      if (x.bold) marks.push('strong'); if (x.italic) marks.push('em'); if (x.code) marks.push('code');
      if (x.href) { const k = key(); markDefs.push({ _key: k, _type: 'link', href: x.href }); marks.push(k); }
      return { _type: 'span', _key: key(), text: x.text, marks };
    });
    return Object.assign({ _type: 'block', _key: key(), style: 'normal', markDefs, children }, extra || {});
  };
  const out = [];
  for (const b of parseMarkdown(md)) {
    if (b.type === 'heading') out.push(block(b.inlines, { style: 'h' + b.level }));
    else if (b.type === 'quote') out.push(block(b.inlines, { style: 'blockquote' }));
    else if (b.type === 'list') for (const it of b.items) out.push(block(it, { listItem: b.ordered ? 'number' : 'bullet', level: 1 }));
    else out.push(block(b.inlines));
  }
  return out;
}


let baseId = String(IN.postId || '').trim().replace(/^drafts\./, '');
if (!baseId) baseId = 'supermat-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const draftId = 'drafts.' + baseId;

let url, body, mode;
if (A && A.title) {
  const slug = String(A.slug || '').trim() || String(A.title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 90);
  const doc = {
    _type: docType,
    title: String(A.title),
    slug: { _type: 'slug', current: slug },
    excerpt: String(A.excerpt || ''),
    [bodyField]: markdownToPortableText(A.bodyMarkdown || A.body || ''),
  };
  if (action === 'publish') doc.publishedAt = new Date().toISOString();
  const mutations = action === 'publish'
    ? [{ createOrReplace: Object.assign({ _id: baseId }, doc) }, { delete: { id: draftId } }]
    : [{ createOrReplace: Object.assign({ _id: draftId }, doc) }];
  url = API + '/data/mutate/' + encodeURIComponent(dataset) + '?returnIds=true&visibility=sync';
  body = { mutations };
  mode = 'mutate';
} else {
  if (!IN.postId) throw new Error('Tidak ada artikel maupun postId untuk diproses.');
  url = API + '/data/actions/' + encodeURIComponent(dataset);
  body = { actions: [{ actionType: 'sanity.action.document.publish', draftId, publishedId: baseId }] };
  mode = 'publishDraft';
}

return [{ json: {
  cmsType: 'sanity', action, mode, projectId, dataset, docType, baseId,
  url, body, auth: 'Bearer ' + String(S.token || '').trim(),
  studioUrl: String(S.studioUrl || '').trim().replace(/\/+$/, ''),
  publicUrlPattern: String(S.publicUrlPattern || '').trim(),
  slug: A && A.title ? body.mutations[0].createOrReplace.slug.current : '',
  title: A ? A.title || '' : '',
  requestId: IN.requestId || '',
} }];

// Adapter Sanity — rapikan respons Sanity jadi format standar Supermat
const P = $('Siapkan Sanity').first().json;
const R = $input.first().json || {};
const status = Number(R.statusCode || 0);
let body = R.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { raw: body.slice(0, 300) }; } }
body = body || {};
const ok = status >= 200 && status < 300 && !body.error;

if (!ok) {
  const detail = (body.error && (body.error.description || body.error.message || body.error)) || body.message || body.raw || (R.error && (R.error.message || String(R.error))) || ('HTTP ' + status);
  let msg = 'Sanity menolak permintaan: ' + (typeof detail === 'string' ? detail : JSON.stringify(detail));
  if (status === 401) msg = 'Token Sanity tidak valid (401). Buat token baru di sanity.io/manage → API → Tokens dengan izin Editor.';
  if (status === 403) msg = 'Token Sanity tidak punya izin menulis (403). Pakai token dengan izin Editor, bukan Viewer.';
  if (status === 404) msg = 'Project ID atau dataset Sanity tidak ditemukan (404). Cek Project ID & nama dataset.';
  if (P.mode === 'publishDraft' && status === 409) msg = 'Draf di Sanity tidak ditemukan atau sudah terbit — buka Studio untuk mengecek.';
  if (!status) msg = 'Tidak bisa menghubungi Sanity: ' + msg;
  return [{ json: { status: 'error', cmsType: 'sanity', action: P.action, httpStatus: status, message: msg, requestId: P.requestId } }];
}

const published = P.action === 'publish';
const editId = published ? P.baseId : 'drafts.' + P.baseId;
const draftEditUrl = P.studioUrl
  ? P.studioUrl + '/intent/edit/id=' + encodeURIComponent(P.baseId) + ';type=' + encodeURIComponent(P.docType)
  : 'https://www.sanity.io/manage/project/' + P.projectId;
const publicUrl = published && P.publicUrlPattern && P.slug ? P.publicUrlPattern.replace('{slug}', P.slug) : '';
return [{ json: {
  status: 'ok', cmsType: 'sanity', action: P.action,
  postId: P.baseId, documentId: editId, postStatus: published ? 'publish' : 'draft',
  draftEditUrl, publicUrl, previewUrl: '',
  title: P.title,
  message: published ? 'Artikel terbit di Sanity.' : 'Draf tersimpan di Sanity.',
  requestId: P.requestId,
} }];
